// 단계 히어로 — 실험 테마색 + 큰 이모지로 시각적 무게를 줌 (예상/정리 단계의 허전함 해소)
function StepHero({ exp, label, line }) {
  return (
    <div className="rounded-2xl p-7 border border-white/10 flex flex-col justify-center items-center text-center gap-3"
      style={{ background: `radial-gradient(circle at 50% 25%, ${exp.color}1f, transparent 72%)` }}>
      <div className="w-24 h-24 rounded-3xl flex items-center justify-center text-5xl"
        style={{ background: exp.color + '22', boxShadow: `0 0 44px ${exp.color}55`, border: `1px solid ${exp.color}66` }}>
        {exp.emoji}
      </div>
      <p className="text-[11px] font-bold tracking-[0.2em]" style={{ color: exp.color }}>{label}</p>
      <h3 className="text-xl font-bold text-white">{exp.title}</h3>
