}

// 선택형 문제 카드 (App 밖 정의)
function ChoiceCard({ data, choice, onChoose, accent }) {
  const answered = choice !== null;
  return (
    <div>
      <p className="text-base font-semibold text-white mb-3">{data.q}</p>
      <div className="flex flex-col gap-2">
        {data.options.map((opt, idx) => {
          const isCorrect = idx === data.answer;
          const isChosen = idx === choice;
          let cls = 'bg-white/5 text-slate-200 hover:bg-white/10 border-white/10';
          if (answered) {
            if (isCorrect) cls = 'bg-emerald-500/20 text-emerald-200 border-emerald-400/60';
            else if (isChosen) cls = 'bg-rose-500/20 text-rose-200 border-rose-400/60';
            else cls = 'bg-white/[0.02] text-slate-500 border-white/5';
          }
          return (
            <button key={idx} disabled={answered} onClick={() => onChoose(idx)}
              className={`text-left px-4 py-3 rounded-xl border transition-all flex items-center gap-3 ${cls} ${!answered ? 'hover:translate-x-0.5' : ''}`}>
              <span className="w-7 h-7 rounded-lg bg-white/10 flex items-center justify-center text-sm font-bold flex-shrink-0">{String.fromCharCode(65 + idx)}</span>
              <span className="flex-1">{opt}</span>
              {answered && isCorrect && <span>✅</span>}
              {answered && isChosen && !isCorrect && <span>❌</span>}
            </button>
          );
        })}
      </div>
      {answered && (
        <div className={`mt-3 p-3 rounded-xl text-sm leading-relaxed ${choice === data.answer ? 'bg-emerald-500/10 text-emerald-200' : 'bg-amber-500/10 text-amber-200'}`}>
          {choice === data.answer ? '정답이에요! ' : '아쉬워요! '}{data.explain}
        </div>
      )}
    </div>
  );
}

// 원형 게이지 — 현재값을 채워지는 도넛으로 보여줌 (값이 추상 숫자가 아니라 '양'으로 와닿게)
function Gauge({ value, min, max, color, unit }) {
  const pct = Math.max(0, Math.min(1, (value - min) / (max - min)));
  const deg = pct * 360;
  return (
    <div className="relative mx-auto" style={{ width: 172, height: 172 }}>
      <div className="absolute inset-0 rounded-full" style={{ background: `conic-gradient(${color} ${deg}deg, rgba(255,255,255,0.06) ${deg}deg)`, transition: 'background 0.18s linear', boxShadow: `0 0 28px ${color}55` }} />
      <div className="absolute rounded-full flex flex-col items-center justify-center" style={{ inset: 13, background: 'radial-gradient(circle at 50% 35%, #1e293b, #0f172a)', boxShadow: `inset 0 0 26px ${color}22` }}>
        <span className="text-[40px] font-extrabold leading-none tabular-nums" style={{ color }}>{value}</span>
        <span className="text-sm text-slate-500 mt-1">{unit || '단위 없음'}</span>
      </div>
    </div>
  );
}

// 실시간 차트 + 측정 분석 (App 밖 정의)
function MeasurePanel({ exp }) {
  const canvasRef = useRef(null);
  const chartRef = useRef(null);
  const lastUiRef = useRef(0);
  const tickRef = useRef(0);
  const sumRef = useRef(0);
  const countRef = useRef(0);
  const missionRef = useRef(false);
  const [current, setCurrent] = useState(0);
  const [avg, setAvg] = useState(null);
  const [minSeen, setMinSeen] = useState(null);
  const [maxSeen, setMaxSeen] = useState(null);
  const [missionDone, setMissionDone] = useState(false);
  const [ledOn, setLedOn] = useState(false);

  useEffect(() => {
    const ctx = canvasRef.current.getContext('2d');
    const grad = ctx.createLinearGradient(0, 0, 0, 280);
    grad.addColorStop(0, exp.color + '66');
    grad.addColorStop(1, exp.color + '05');

    const chart = new Chart(canvasRef.current, {
      type: 'line',
      data: { labels: [], datasets: [{ label: exp.title, data: [], borderColor: exp.color, backgroundColor: grad, borderWidth: 2.5, pointRadius: 0, fill: true, tension: 0.3 }] },
      options: {
        animation: false, responsive: false,
        plugins: { legend: { display: false } },
        scales: {
          x: { display: false },
          y: { min: exp.min, max: exp.max, ticks: { color: '#94a3b8', font: { size: 11 } }, grid: { color: 'rgba(255,255,255,0.05)' } },
        },
      },
    });
    chartRef.current = chart;

    const off = MODI.onValue(exp.sensorType, 1, exp.field, (raw) => {
      const value = Math.round((raw || 0) * 10) / 10;
      const ds = chart.data.datasets[0].data;
      chart.data.labels.push(tickRef.current++);
      ds.push(value);
      if (ds.length > WINDOW) { chart.data.labels.shift(); ds.shift(); }
      chart.update('none');

      sumRef.current += value;
      countRef.current += 1;
      if (!missionRef.current && exp.mission.test(value)) { missionRef.current = true; setMissionDone(true); }

      const now = performance.now();
      if (now - lastUiRef.current > 140) {
        lastUiRef.current = now;
        setCurrent(value);
        setAvg(Math.round((sumRef.current / countRef.current) * 10) / 10);
        setMinSeen((p) => (p === null ? value : Math.min(p, value)));
        setMaxSeen((p) => (p === null ? value : Math.max(p, value)));
      }
    }, { pollMs: 50 });

    return () => { off(); chart.destroy(); };
  }, [exp.key]);

  const resetData = () => {
    const chart = chartRef.current;
    if (chart) { chart.data.labels = []; chart.data.datasets[0].data = []; chart.update('none'); }
    tickRef.current = 0; sumRef.current = 0; countRef.current = 0; missionRef.current = false;
    setCurrent(0); setAvg(null); setMinSeen(null); setMaxSeen(null); setMissionDone(false);
  };

  const toggleLed = () => {
    if (ledOn) { MODI.led(1).off(); setLedOn(false); }
    else { MODI.led(1).setColor(255, 200, 60); setLedOn(true); }
  };

  return (
    <div className="grid grid-cols-3 gap-5">
      <div className="col-span-2 rounded-2xl p-5 border border-white/10 bg-white/[0.03]">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-lg font-semibold text-white flex items-center gap-2">
            <span className="w-2 h-2 rounded-full animate-pulse" style={{ background: exp.color }} />실시간 측정 그래프
          </h2>
          <button onClick={resetData} className="px-3 py-1.5 text-sm rounded-lg bg-white/5 hover:bg-white/10 text-slate-300 transition border border-white/10">↺ 기록 초기화</button>
        </div>
        <canvas ref={canvasRef} width={620} height={280} />
        <div className={`mt-4 p-3.5 rounded-xl border flex items-center gap-3 transition-all ${missionDone ? 'bg-emerald-500/15 border-emerald-400/60' : 'bg-white/[0.02] border-white/10'}`}>
          <span className="text-2xl">{missionDone ? '🏆' : '🎯'}</span>
          <div>
            <p className="text-xs text-slate-500">도전 미션</p>
            <p className={`text-sm font-semibold ${missionDone ? 'text-emerald-300' : 'text-slate-200'}`}>{exp.mission.label}{missionDone && ' — 성공! 🎉'}</p>
          </div>
        </div>
        <div className="mt-3 p-3.5 rounded-xl bg-white/[0.02] border border-white/10 flex items-start gap-2.5">
          <span className="text-lg">👀</span>
          <div>
            <p className="text-xs text-slate-500">관찰 포인트</p>
            <p className="text-sm text-slate-300 leading-relaxed">{exp.observe}</p>
          </div>
        </div>
      </div>

      <div className="flex flex-col gap-4">
        <div className="rounded-2xl p-5 border border-white/10 bg-white/[0.03] text-center">
          <p className="text-sm text-slate-400 mb-3">현재 측정값</p>
          <Gauge value={current} min={exp.min} max={exp.max} color={exp.color} unit={exp.unit} />
          <div className="grid grid-cols-3 gap-2 mt-4 text-sm">
            <div className="rounded-lg bg-white/[0.03] py-2"><p className="text-slate-500 text-xs">최저</p><p className="text-cyan-300 font-bold">{minSeen === null ? '-' : minSeen}</p></div>
            <div className="rounded-lg bg-white/[0.03] py-2"><p className="text-slate-500 text-xs">평균</p><p className="text-white font-bold">{avg === null ? '-' : avg}</p></div>
            <div className="rounded-lg bg-white/[0.03] py-2"><p className="text-slate-500 text-xs">최고</p><p className="text-rose-300 font-bold">{maxSeen === null ? '-' : maxSeen}</p></div>
          </div>
        </div>

        <div className="rounded-2xl p-5 border border-white/10 bg-white/[0.03] flex-1">
          <p className="text-sm font-semibold text-slate-300 mb-2">🔬 탐구 개념</p>
          <p className="text-sm text-slate-400 leading-relaxed">{exp.concept}</p>
        </div>

        {exp.ledReactive && (
          <button onClick={toggleLed} className={`px-4 py-3 rounded-2xl font-semibold transition-all ${ledOn ? 'bg-amber-400 text-slate-900 shadow-lg shadow-amber-400/30' : 'bg-white/5 text-slate-200 hover:bg-white/10 border border-white/10'}`}>
            {ledOn ? '💡 LED 켜짐 (끄기)' : '🔆 LED로 빛 만들기'}
          </button>
        )}
      </div>
    </div>
  );
}

// 실험 한 개의 탐구 흐름 (예상 → 측정 → 정리)
function ExperimentFlow({ exp }) {
  const [step, setStep] = useState(0);
  const [predChoice, setPredChoice] = useState(null);
  const [quizChoice, setQuizChoice] = useState(null);

  return (
    <div className="h-full flex flex-col min-h-0">
      {/* 단계 진행 표시 (상단 고정) */}
      <div className="flex items-center gap-2 mb-5 flex-shrink-0">
        {STEPS.map((s, idx) => {
          const isActive = step === idx;
          const isDone = step > idx;
          return (
            <React.Fragment key={idx}>
              <button onClick={() => setStep(idx)}
                className={`flex items-center gap-2 px-4 py-2.5 rounded-xl font-medium transition-all border ${
                  isActive ? 'text-slate-900 border-transparent' : isDone ? 'bg-white/5 text-slate-300 border-white/10' : 'bg-white/[0.02] text-slate-500 border-white/5'}`}
                style={isActive ? { background: exp.color, boxShadow: `0 4px 16px ${exp.color}55` } : undefined}>
                <span>{isDone ? '✓' : s.icon}</span>
                <span className="text-sm">{idx + 1}. {s.label}</span>
              </button>
              {idx < STEPS.length - 1 && <div className="flex-1 h-px bg-white/10 min-w-3" />}
            </React.Fragment>
          );
        })}
      </div>

      {/* 콘텐츠 영역: 남은 높이를 채우고, 짧으면 세로 중앙 정렬·길면 스크롤 (화면 높이에 동적 대응) */}
      <div className="flex-1 min-h-0 overflow-y-auto">
       <div className="min-h-full flex flex-col py-1">
      {step === 0 && (
        <div className="grid md:grid-cols-2 gap-5 items-stretch flex-1">
          <StepHero exp={exp} label="STEP 1 · 예상하기"
            line="직접 재보기 전에, 결과가 어떻게 될지 먼저 맞혀볼까요? 과학자처럼 가설을 세워보는 거예요." />
          <div className="rounded-2xl p-6 border border-white/10 bg-white/[0.03] flex flex-col justify-center">
            <ChoiceCard data={exp.prediction} choice={predChoice} onChoose={setPredChoice} accent={exp.color} />
            {predChoice !== null && (
              <button onClick={() => setStep(1)} className="mt-5 w-full px-5 py-3 rounded-xl text-white font-semibold transition-all hover:scale-[1.02]" style={{ background: exp.color, boxShadow: `0 4px 16px ${exp.color}55` }}>
                측정하러 가기 →
              </button>
            )}
          </div>
        </div>
      )}

      {step === 1 && (
        <div>
          <MeasurePanel exp={exp} />
          <button onClick={() => setStep(2)} className="mt-5 px-5 py-2.5 rounded-xl bg-emerald-500 hover:bg-emerald-400 text-white font-semibold transition-all hover:scale-[1.02]">
            정리하러 가기 →
          </button>
        </div>
      )}

      {step === 2 && (
        <div className="grid md:grid-cols-2 gap-5 items-stretch flex-1">
          <StepHero exp={exp} label="STEP 3 · 정리하기"
            line="측정하며 관찰한 내용을 떠올려 보세요. 마지막 퀴즈로 개념을 확인하고 실생활 연결까지!" />
          <div className="rounded-2xl p-6 border border-white/10 bg-white/[0.03]">
            <ChoiceCard data={exp.quiz} choice={quizChoice} onChoose={setQuizChoice} accent={exp.color} />
            {quizChoice !== null && (
              <div className="mt-5 flex flex-col gap-3">
              <div className="p-4 rounded-xl border" style={{ background: exp.color + '12', borderColor: exp.color + '55' }}>
                <p className="text-sm font-semibold text-white mb-1">🌍 실생활에서는?</p>
                <p className="text-sm text-slate-300 leading-relaxed">{exp.realWorld}</p>
              </div>
              <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-400/40">
                <p className="text-sm font-semibold text-emerald-200">🎓 {exp.title} 탐구 완료!</p>
                <p className="text-sm text-slate-300 mt-1">예상하고 → 측정하고 → 정리하며 <b className="text-white">{exp.title}</b>의 원리를 직접 확인했어요.</p>
              </div>
            </div>
          )}
          </div>
        </div>
      )}
       </div>
      </div>
    </div>
  );
}

function App() {
  const [activeKey, setActiveKey] = useState(EXPERIMENTS[0].key);
  const active = EXPERIMENTS.find((e) => e.key === activeKey);

  return (
    // 화면 높이를 꽉 채우는 세로 flex — 상단(헤더·탭)은 고정, 아래 콘텐츠가 남은 높이를 차지
    <div className="h-screen flex flex-col text-slate-100" style={{ background: 'radial-gradient(circle at 50% -20%, #1e293b 0%, #0f172a 55%, #020617 100%)' }}>
      <div className="w-full max-w-5xl mx-auto px-6 pt-6 flex-shrink-0">
        <header className="mb-5">
          <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-white/5 border border-white/10 text-[11px] font-semibold tracking-widest text-cyan-300/80 mb-3">
            MODI SCIENCE LAB · 센서로 배우는 과학
          </div>
          <h1 className="text-3xl font-extrabold flex items-center gap-2.5">
            <span>🧪</span>
            <span className="bg-gradient-to-r from-cyan-300 via-emerald-300 to-amber-300 bg-clip-text text-transparent">모디 과학 탐구 실험실</span>
          </h1>
          <p className="text-slate-400 text-sm mt-2">🤔 예상하고 → 📡 직접 측정하고 → 🎓 정리하며 과학 개념을 몸으로 익혀 보세요.</p>
        </header>

        <div className="flex flex-wrap gap-2.5">
          {EXPERIMENTS.map((exp) => {
            const on = activeKey === exp.key;
