              <button key={exp.key} onClick={() => setActiveKey(exp.key)}
                className={`px-4 py-2.5 rounded-xl font-medium transition-all flex items-center gap-2 border ${on ? 'text-white' : 'bg-white/[0.03] text-slate-300 border-white/10 hover:bg-white/[0.07]'}`}
                style={on ? { background: exp.color + '22', borderColor: exp.color, boxShadow: `0 4px 16px ${exp.color}33` } : undefined}>
